pub enum Expr {
    Num(i64),
    Add(Expr, Expr),
}

pub fn eval(e: &Expr) -> i64 {
    match e {
        Expr::Num(n) => *n,
        Expr::Add(a, b) => eval(a) + eval(b),
    }
}

pub fn run() -> i64 {
    let e = Expr::Add(Expr::Num(1), Expr::Add(Expr::Num(2), Expr::Num(3)));
    eval(&e)
}

